\title[The $D_6$ splitting-type channel of $x^6-2$]{The $D_6$ Splitting-Type Channel of $x^6-2$:\\ Exact Entropies, an Abelian Ceiling,\\ and a Non-Abelian Residue}
\author{Aristotle}
\date{September 2026}

\begin{document}

\begin{abstract}
For a prime $p\ge 5$ let $T(p)$ be the number of roots of $x^6-2$ in $\F_p$. Empirically $T(p)$ takes only the values $0,2,6$, with frequencies near $66\%,25\%,8\%$. Its Shannon entropy is about $1.18$ bits, the residue $p \bmod 3$ shares about $0.363$ bits with it, and for semiprimes $N=pq$ the residue $N\bmod 3$ shares about $0.132$ bits with the type pair. We explain all of these numbers exactly. The Galois group of the splitting field is the dihedral group $D_6$, acting on the six roots as on the vertices of a hexagon. Assuming Chebotarev equidistribution, $T$ is distributed as the number of fixed vertices of a uniform element of $D_6$. We prove the fixed-point law of $D_n$ for every even $n$ and an unconditional prime-level root law ($T(p)\in\{0,6\}$ for $p\equiv1\pmod 3$, and $T(p)=2\cdot[p\equiv\pm1\pmod 8]$ for $p\equiv 2\pmod 3$). We obtain the closed forms $H(T)=\tfrac34\log_2 3$, $I(p\bmod 3;T)=\tfrac14\log_23+\tfrac5{12}\log_25-1$ and $I(D_6^{\ab};T)=\tfrac12\log_23+\tfrac16$, and for the pair channel $I_{\mathrm{pair}}=\tfrac38\log_23+\tfrac{35}{72}\log_25+\tfrac{17}{72}\log_2 17-\tfrac{23}{9}$. We prove an abelian ceiling valid for every finite group: no dial factoring through an abelian quotient beats the abelianisation. For $D_6$ this leaves a non-abelian residue of at least $\tfrac14\log_23-\tfrac16>0.22$ bits. Finally, we show that information and prediction diverge: $p\bmod 3$ carries $0.36$ bits but gives no Bayes-error gain, and every abelian dial misclassifies at least $1/12$ of Frobenius classes, a floor attained by $p\bmod 24$. The structural source of the residue is the commutator identity $[r_1,s_0]=r_2$.
\end{abstract}

\maketitle

\section{Introduction}

For an irreducible $f\in\Z[x]$ with splitting field $K$ and Galois group $G$, the number of roots of $f$ modulo an unramified prime $p$ equals the number of roots fixed by the Frobenius element $\Frob_p\in G$. The Chebotarev density theorem says that $\Frob_p$ is equidistributed in $G$. Root-count statistics are therefore fixed-point statistics of a uniformly random group element. We call this random variable the \emph{type} $T$. A \emph{dial} is a coarse function of the prime, such as $p\bmod m$, whose information about $T$ we measure. When $G$ is abelian, class field theory says congruences see everything about $\Frob_p$, so the first interesting test is a non-abelian $G$.

This paper treats $f=x^6-2$, with $G=D_6$. Every experimental value turns out to be an exact closed-form quantity attached to $D_6$. A fully general inequality, the \emph{abelian ceiling}, quantifies what congruences can never see. For $x^6-2$ this is $\tfrac14\log_23-\tfrac16\approx0.2296$ bits, about $19.3\%$ of $H(T)$.

\medskip
\noindent\textbf{Standing hypothesis.} The only analytic input is Chebotarev equidistribution of $\Frob_p$ in $D_6$. We use it as a modelling hypothesis and do not re-prove it. All group-side statements are exact, and the prime-level root law of Section~\ref{sec:roots} holds unconditionally for every prime.

\section{The splitting field and its Galois group}

Let $\alpha=2^{1/6}$ and $\zeta=e^{2\pi i/6}=\tfrac{1+\sqrt{-3}}2$. The roots of $x^6-2$ are $\zeta^j\alpha$ for $j\in\Z/6$, and the splitting field is $K=\Q(2^{1/6},\sqrt{-3})$, with $[K:\Q]=12$.

\begin{definition}
The dihedral group $D_n$ of order $2n$ consists of rotations $r_i$ and reflections $s_i$ ($i\in\Z/n$), with
\[ r_ir_j=r_{i+j},\quad r_is_j=s_{j-i},\quad s_ir_j=s_{i+j},\quad s_is_j=r_{j-i}. \]
It acts on the vertex set $\Z/n$ by $r_i\cdot j=i+j$ and $s_i\cdot j=-i-j$.
\end{definition}

\begin{lemma}
This is a group action.
\end{lemma}
\begin{proof}
Check the four cases. For example, $s_i\cdot(s_k\cdot j)=(k-i)+j=(s_is_k)\cdot j$ and $r_i\cdot(s_k\cdot j)=-(k-i)-j=(r_is_k)\cdot j$.
\end{proof}

The automorphism with $\alpha\mapsto\zeta^i\alpha$ and $\sqrt{-3}\mapsto\sqrt{-3}$ acts by $j\mapsto i+j$, so it is $r_i$. The automorphism with $\alpha\mapsto\zeta^{-i}\alpha$ and $\sqrt{-3}\mapsto-\sqrt{-3}$ acts by $j\mapsto -i-j$, so it is $s_i$. Hence $\mathrm{Gal}(K/\Q)\cong D_6$ with its hexagon action.

\begin{definition}
For $g\in D_n$ let $\fix(g)=\#\{j:g\cdot j=j\}$. For a prime $p\ge5$ the \emph{type} is $T(p)=\#\{x\in\F_p:x^6=2\}=\fix(\Frob_p)$.
\end{definition}

\section{Group-theoretic core}

\begin{theorem}[Rotations]
$\fix(r_i)=n$ if $i=0$, and $\fix(r_i)=0$ otherwise.
\end{theorem}

\begin{theorem}[Reflections, $n$ even]\label{thm:refl}
Let $n$ be even and $0\le i<n$. Then $\fix(s_i)=2$ if $i$ is even, and $\fix(s_i)=0$ if $i$ is odd.
\end{theorem}
\begin{proof}
The fixed points are the solutions of $2j=-i$ in $\Z/n$. Doubling is an additive endomorphism of the cyclic group $\Z/n$ with kernel of size $\gcd(n,2)=2$, so every nonempty fibre has $2$ elements. Reducing modulo $2$ shows that $-i$ is a double only if $i$ is even. If $i=2t$, then $j=-t$ is a solution.
\end{proof}

\begin{corollary}
For even $n$, every element of $D_n$ fixes $0$, $2$ or $n$ vertices.
\end{corollary}

\begin{theorem}[The $D_6$ type distribution]
In $D_6$, exactly $8$ elements fix no vertex ($r_1,\dots,r_5,s_1,s_3,s_5$), $3$ fix two ($s_0,s_2,s_4$), and one fixes six ($r_0$). Thus $\Pr[T=0]=\tfrac23$, $\Pr[T=2]=\tfrac14$ and $\Pr[T=6]=\tfrac1{12}$.
\end{theorem}

\begin{remark}
$\sum_{g}\fix(g)=12=|D_6|$. This is Burnside's lemma for the single orbit of the six roots.
\end{remark}

\begin{definition}
The rotation character $\rho:D_n\to\Z/2$ is $\rho(r_i)=0$, $\rho(s_i)=1$. For even $n$, the map $\pi:D_n\to\Z/2\times\Z/2$ is $\pi(r_i)=(0,i\bmod2)$, $\pi(s_i)=(1,i\bmod 2)$.
\end{definition}

\begin{proposition}
$\rho$ and $\pi$ are homomorphisms, and $\pi_1=\rho$.
\end{proposition}

Arithmetically, $\rho(\Frob_p)$ is the action on $\sqrt{-3}$. It is trivial if and only if $p\equiv1\pmod3$. The second coordinate of $\pi$ is the action on $\sqrt2=\alpha^3$ (note $r_i(\alpha^3)=(-1)^i\alpha^3$), which is trivial if and only if $p\equiv\pm1\pmod 8$. So $\pi(\Frob_p)$ is determined by $p\bmod 24$.

\begin{proposition}[Commutator]\label{prop:comm}
In every $D_n$, $[r_1,s_0]=r_1s_0r_1^{-1}s_0^{-1}=r_2$.
\end{proposition}

\begin{corollary}\label{cor:ab}
In $D_6$, $\ker\pi=\{r_0,r_2,r_4\}$ lies in the commutator subgroup, and $\pi$ induces an isomorphism $D_6^{\ab}\cong\Z/2\times\Z/2$. Two elements have the same $\pi$-image if and only if they have the same image in $D_6^{\ab}$.
\end{corollary}
\begin{proof}
$r_2$ is a commutator and $r_4=r_2^2$. If $\pi(g)=\pi(h)$ then $g=r_kh$ with $k\in\{0,2,4\}$. Conversely, $\pi$ factors through $D_6^{\ab}$ because its target is abelian.
\end{proof}

\section{The prime-level root law}\label{sec:roots}

\begin{theorem}[Cyclic root law]\label{thm:cyc}
In a finite cyclic group of order $n$, the equation $x^k=a$ has $0$ or exactly $\gcd(n,k)$ solutions.
\end{theorem}
\begin{proof}
If there is a solution, the solution set is a coset of the kernel of $x\mapsto x^k$, which has $\gcd(n,k)$ elements.
\end{proof}

\begin{corollary}
In $\F_q$, for $a\neq0$ and $k\ge1$, the equation $x^k=a$ has $0$ or $\gcd(q-1,k)$ solutions.
\end{corollary}

\begin{theorem}[Dichotomy]
For every odd prime $p$, $T(p)\in\{0,\gcd(p-1,6)\}$.
\end{theorem}

\begin{theorem}[Rotation half]
If $p\equiv1\pmod3$ is prime, then $T(p)\in\{0,6\}$.
\end{theorem}

\begin{theorem}[Reflection half]\label{thm:reflhalf}
If $p\ne2$ is prime and $p\equiv2\pmod3$, then $T(p)=2$ when $p\equiv\pm1\pmod8$, and $T(p)=0$ otherwise.
\end{theorem}
\begin{proof}
Here $\gcd(p-1,6)=2$. If $x^6=2$ then $(x^3)^2=2$. Conversely, if $y^2=2$, choose $e$ with $3e=2(p-1)+1$. Then $(y^e)^6=(y^{p-1}y^{p-1}y)^2=2$. So a sixth root exists if and only if $2$ is a square, which by the second supplementary law holds if and only if $p\equiv\pm1\pmod8$.
\end{proof}

\begin{theorem}[Conductor $24$]\label{thm:24}
For every prime $p\ge5$: if $p\equiv5,11,13,19\pmod{24}$ then $T(p)=0$; if $p\equiv17,23\pmod{24}$ then $T(p)=2$; and if $p\equiv1,7\pmod{24}$ then $T(p)\in\{0,6\}$.
\end{theorem}
\begin{proof}
In the first case $p\equiv\pm3\pmod8$, so $2$ is not a square, and $x^6=2$ would give $(x^3)^2=2$. The other cases are the two halves above.
\end{proof}

\begin{remark}
The least prime $p\ge5$ with $T(p)=6$ is $31$, since $2^5\equiv1$ gives $2^6\equiv2$. Also $T(5)=T(7)=T(11)=T(13)=T(19)=0$ and $T(23)=T(47)=2$. For $p\equiv1,7\pmod{24}$, the value depends on whether $2$ is a sixth power modulo $p$, which is not a congruence condition on $p$. This is the arithmetic face of Corollary~\ref{cor:ab}.
\end{remark}

\section{A counting information calculus}

Let $S$ be finite and uniform, let $g:S\to B$ be a read-out, and let $k:S\to C$ be a dial. Write $S_c=k^{-1}(c)$.

\begin{definition}
$H_S(g)=-\sum_b\frac{|g^{-1}(b)|}{|S|}\log_2\frac{|g^{-1}(b)|}{|S|}$, \quad $H_S(g\mid k)=\sum_{c}\frac{|S_c|}{|S|}H_{S_c}(g)$, \quad $I_S(g;k)=H_S(g)-H_S(g\mid k)$.
\end{definition}

If the fibre sizes of $g$ are $m_1,\dots,m_t$ with sum $M$, then
\begin{equation}\label{eq:count}
H_S(g)=\log_2M-\frac1M\sum_i m_i\log_2 m_i.
\end{equation}

\begin{lemma}[Average form]
$H_S(g\mid k)=\frac1{|S|}\sum_{a\in S}H_{S_{k(a)}}(g)$.
\end{lemma}

\begin{lemma}[Gibbs]
$0\le H_S(g\mid k)\le H_S(g)$.
\end{lemma}

\begin{theorem}[Refinement monotonicity]\label{thm:refine}
If $k'$ refines $k$ on $S$ (that is, $k'(a)=k'(b)\Rightarrow k(a)=k(b)$), then $H_S(g\mid k')\le H_S(g\mid k)$, equivalently $I_S(g;k)\le I_S(g;k')$.
\end{theorem}
\begin{proof}
Each $k$-fibre $S_c$ is a disjoint union of $k'$-fibres. The Gibbs inequality inside $S_c$ gives $H_{S_c}(g\mid k')\le H_{S_c}(g)$. Averaging over $c$ with weights $|S_c|/|S|$ gives the claim.
\end{proof}

\begin{corollary}
Dials with the same level-set partition give equal conditional entropies.
\end{corollary}

\begin{theorem}[Abelian ceiling]\label{thm:ceiling}
Let $G$ be a finite group, $g$ any read-out on $G$, and $\varphi:G\to A$ any homomorphism to an abelian group. Then $I_G(g;\varphi)\le I_G(g;\ab)$, where $\ab:G\to G^{\ab}$.
\end{theorem}
\begin{proof}
$\varphi$ factors through $G^{\ab}$, so $\ab$ refines $\varphi$. Apply Theorem~\ref{thm:refine}.
\end{proof}

By the Kronecker--Weber theorem, a congruence dial $p\bmod m$ sees $\Frob_p$ only through an abelian quotient of $\mathrm{Gal}(K/\Q)$. Under Chebotarev, therefore, no congruence dial carries more information about a Frobenius statistic than the abelianisation.

\section{Exact values of the $D_6$ type channel}

Write $L=\log_23$, $L_5=\log_25$ and $L_{17}=\log_217$.

\begin{theorem}[Type entropy]
$H(T)=\tfrac34L\approx1.18872$.
\end{theorem}
\begin{proof}
The fibre sizes are $1,8,3$, so by \eqref{eq:count} $H(T)=\log_212-\tfrac1{12}(24+3L)=\tfrac34L$.
\end{proof}

\begin{theorem}[Conductor-$3$ dial]
The rotation fibre (types $\{6{:}1,0{:}5\}$) has entropy $1+L-\tfrac56L_5$, and the reflection fibre (types $\{2{:}3,0{:}3\}$) has entropy $1$. Hence $H(T\mid\rho)=1+\tfrac12L-\tfrac5{12}L_5$ and
\[ I(\rho;T)=\tfrac14L+\tfrac5{12}L_5-1\approx0.36371, \]
with $0.34<I(\rho;T)<0.375$ and $0<I(\rho;T)<H(T)$.
\end{theorem}

\begin{theorem}[Full abelian dial]
$H(T\mid\pi)=\tfrac14L-\tfrac16\approx0.22957$ and $I(\pi;T)=\tfrac12L+\tfrac16\approx0.95915$.
\end{theorem}
\begin{proof}
The fibres of $\pi$ are $\{r_0,r_2,r_4\}$ (types $6,0,0$), $\{r_1,r_3,r_5\}$ (all $0$), $\{s_0,s_2,s_4\}$ (all $2$) and $\{s_1,s_3,s_5\}$ (all $0$). Only the first has positive entropy, $L-\tfrac23$, and it has weight $\tfrac14$.
\end{proof}

\begin{theorem}[Ceiling and residue for $D_6$]
For every homomorphism $\varphi$ from $D_6$ to an abelian group, $I(\varphi;T)\le\tfrac12L+\tfrac16$ and $H(T\mid\varphi)\ge\tfrac14L-\tfrac16>0.22$.
\end{theorem}
\begin{proof}
Combine Corollary~\ref{cor:ab} and Theorem~\ref{thm:ceiling}. For the bound, use $L>19/12$, which is equivalent to $3^{12}>2^{19}$.
\end{proof}

\begin{corollary}[Dial hierarchy]
$0<I(p\bmod3;T)<I(p\bmod24;T)<H(T)$. The abelian ceiling captures the fraction $(L/2+1/6)/(3L/4)\approx0.807$ of the type entropy.
\end{corollary}

\section{The semiprime pair channel}

For $N=pq$, the two Frobenii are independent and uniform on $D_6\times D_6$ ($144$ elements). The dial $N\bmod3$ is $\rho(g_1)+\rho(g_2)\in\Z/2$.

\begin{theorem}
$H(T_1,T_2)=\tfrac32L=2H(T)$.
\end{theorem}

\begin{lemma}\label{lem:pairfib}
Both dial fibres have $72$ elements. In the same-kind fibre the type-pair counts are $(0,0){:}34$, $(0,2){:}9$, $(2,0){:}9$, $(2,2){:}9$, $(0,6){:}5$, $(6,0){:}5$, $(6,6){:}1$. In the opposite-kind fibre they are $(0,0){:}30$, $(0,2){:}15$, $(2,0){:}15$, $(0,6){:}3$, $(6,0){:}3$, $(2,6){:}3$, $(6,2){:}3$. In particular $34=25+9$ collects two blank rotations and two edge-axis reflections.
\end{lemma}

\begin{theorem}[Pair channel]
\[ H(T_1,T_2\mid N\bmod 3)=\tfrac{23}{9}+\tfrac98L-\tfrac{35}{72}L_5-\tfrac{17}{72}L_{17}, \]
\[ I_{\mathrm{pair}}=\tfrac38L+\tfrac{35}{72}L_5+\tfrac{17}{72}L_{17}-\tfrac{23}9\approx0.13262, \]
with $0.07<I_{\mathrm{pair}}<0.15$ and $0<I_{\mathrm{pair}}<I(p\bmod3;T)$.
\end{theorem}
\begin{proof}
Apply \eqref{eq:count} to Lemma~\ref{lem:pairfib}, using $\log_272=3+2L$, $\log_234=1+L_{17}$ and $\log_230=1+L+L_5$. For the enclosure use $4<L_{17}<41/10$, which holds because $17^{10}<2^{41}$.
\end{proof}

\section{Information versus prediction}

For a dial $k$, the minimal number of misclassified elements over all predictors $f\circ k$ is $\sum_c\bigl(|S_c|-\max_t|\{x\in S_c:T(x)=t\}|\bigr)$.

\begin{theorem}
Every constant guess of $T$ errs on at least $4$ of $12$ classes, and the guess $T=0$ attains this.
\end{theorem}

\begin{theorem}[No predictive gain at conductor $3$]
Every predictor $f(\rho(g))$ errs on at least $4$ of $12$ classes.
\end{theorem}
\begin{proof}
The rotation fibre forces at least $1$ error and the reflection fibre at least $3$.
\end{proof}

\begin{theorem}[Non-abelian obstruction]
For every homomorphism $\varphi$ from $D_6$ to an abelian group and every $f$, the predictor $f\circ\varphi$ errs on at least one class.
\end{theorem}
\begin{proof}
By Proposition~\ref{prop:comm}, $\varphi(r_2)=\varphi(r_0)$, but $T(r_0)=6\neq0=T(r_2)$.
\end{proof}

\begin{theorem}[The floor is attained]
The predictor ``$T=2$ if $\pi(g)=(1,0)$, else $T=0$'' errs only on $r_0$. Arithmetically, predict $2$ for $p\equiv17,23\pmod{24}$ and $0$ otherwise.
\end{theorem}

