"""Splitting type of x^6 - 2 modulo a prime via the cyclic root law."""
from __future__ import annotations
import math


def splitting_type(p: int, k: int = 6, a: int = 2) -> int:
    """Number of solutions of x^k = a in F_p (p prime, p not dividing a).

    F_p^* is cyclic of order p-1, so x^k = a has 0 or d = gcd(p-1, k) solutions,
    and a solution exists iff a^((p-1)/d) = 1 (generalised Euler criterion)."""
    d = math.gcd(p - 1, k)
    return d if pow(a, (p - 1) // d, p) == 1 else 0


def congruence_prediction(p: int) -> set[int]:
    """What p mod 24 alone says about T(p) for x^6 - 2."""
    r = p % 24
    if r in (5, 11, 13, 19):
        return {0}
    if r in (17, 23):
        return {2}
    return {0, 6}


if __name__ == "__main__":
    ps = [p for p in range(5, 400) if all(p % q for q in range(2, int(p ** 0.5) + 1))]
    for p in ps[:25]:
        brute = sum(1 for x in range(p) if (x ** 6 - 2) % p == 0)
        t = splitting_type(p)
        assert t == brute and t in congruence_prediction(p)
        print(p, p % 24, t, sorted(congruence_prediction(p)))

"""Abelian ceiling of a permutation-group type channel via commutator-subgroup cosets."""
from __future__ import annotations
import math
from collections import Counter, defaultdict

Perm = tuple[int, ...]


def compose(g: Perm, h: Perm) -> Perm:          # (g h)(j) = g(h(j))
    return tuple(g[h[j]] for j in range(len(h)))


def inverse(g: Perm) -> Perm:
    inv = [0] * len(g)
    for j, gj in enumerate(g):
        inv[gj] = j
    return tuple(inv)


def closure(gens: list[Perm]) -> set[Perm]:
    n = len(gens[0]); e = tuple(range(n))
    group, frontier = {e}, [e]
    while frontier:
        new = []
        for x in frontier:
            for s in gens:
                y = compose(s, x)
                if y not in group:
                    group.add(y); new.append(y)
        frontier = new
    return group


def entropy(counts: list[int]) -> float:
    m = sum(counts)
    return -sum(c / m * math.log2(c / m) for c in counts if c)


def abelian_ceiling(gens: list[Perm]) -> dict[str, float]:
    G = closure(gens)
    comms = [compose(compose(a, b), compose(inverse(a), inverse(b))) for a in G for b in G]
    Gp = closure(comms)                                    # commutator subgroup [G, G]
    coset = {g: min(compose(g, k) for k in Gp) for g in G}  # label of the coset g[G,G]
    fix = lambda g: sum(1 for j, gj in enumerate(g) if gj == j)
    H = entropy(list(Counter(fix(g) for g in G).values()))
    fib: dict[Perm, Counter] = defaultdict(Counter)
    for g in G:
        fib[coset[g]][fix(g)] += 1
    Hc = sum(sum(c.values()) / len(G) * entropy(list(c.values())) for c in fib.values())
    return {"|G|": len(G), "|G^ab|": len(fib), "H(T)": H,
            "ceiling I(G^ab;T)": H - Hc, "residue H(T|G^ab)": Hc}


if __name__ == "__main__":
